import json, sys
spec = json.load(sys.stdin)
for path, methods in spec['paths'].items():
    for method, info in methods.items():
        if method.upper() != 'GET':
            print(f'{method.upper()} {path} - {info.get(\"operationId\", \"\")}')
"

curl -s "$VERACITY_URL/v1/openapi.json" | python3 -c "
import json, sys
spec = json.load(sys.stdin)
for path, methods in spec['paths'].items():
    for method, info in methods.items():
        desc = info.get('description', '').lower()
        if 'session' in desc or 'wait' in desc or 'end' in desc:
            print(f'{method.upper()} {path} - {info.get(\"operationId\", \"\")}')
            print(f'  desc: {info.get(\"description\", \"\")}')
"

